starter:
%dw 2.0
output application/json
var rules = [
  { name: "id-required", test: (r) -> r.id != null },
  { name: "qty-positive", test: (r) -> r.qty > 0 },
  { name: "email-has-at", test: (r) -> (r.email default "") contains "@" }
]
---
payload map (r) -> { id: r.id, errors: (rules filter (not $.test(r))).name default [] }

